// <auto-generated/>
using Sunplus.Agent.Model.BL;
using Sunplus.Agent.Model.Entities;
using System;
using System.Data.Common;
using System.Globalization;
using System.Threading;
using System.Web;

public partial class Error : System.Web.UI.Page
{
    protected string DarkModeName = string.Empty;
    protected string ErrorMessage = null;

    protected override void OnLoad(EventArgs e)
    {   
        DarkModeName = CurrentUserSession.DarkModeName;

        string errCode = Request["err"];

        if (string.IsNullOrWhiteSpace(Request["err"]))
        {
            var ex = Server.GetLastError();
            var inner = ex?.InnerException;
            
            if (ex is DbException || inner is DbException)
            {
                errCode = "5002";
            }
            else if (ex is HttpException)
            {
                errCode = ((HttpException)ex).GetHttpCode().ToString();
            }
            else if (inner is HttpException)
            {
                errCode = ((HttpException)inner).GetHttpCode().ToString();
            }
            else
            {
                errCode = "5000";
            }
        }

        ErrorMessage = string.Format(Alpha.Reports.Site.App_GlobalResources.Resources.HttpError_Default, errCode);
        Server.ClearError();

        base.OnLoad(e);
    }

    protected override void InitializeCulture()
    {
        SetLanguage(CurrentUserSession == null ? "en-US" : CurrentUserSession.Language);
        base.InitializeCulture();
    }

    private void SetLanguage(string language)
    {
        Thread.CurrentThread.CurrentUICulture = new CultureInfo(language);
        Thread.CurrentThread.CurrentCulture = CultureInfo.CreateSpecificCulture(language);
    }

    private IUserSession CurrentUserSession
    {
        get
        {
            if (null == HttpContext.Current.Session) return null;

            return UserSessionService.GetUserSessionInstance(HttpContext.Current.Session.SessionID);
        }
    }
}
